        throw new BoardValidationError(`Invalid cell at (${r}, ${c}); expected 'X', 'O', or null`);
      }
      cells[c] = cell;
    }

    rows[r] = Object.freeze(cells) as unknown as Row;
  }

  return Object.freeze(rows) as unknown as Board;
